const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const subject = j.subject || '(no subject)';
  const from = j.from?.value?.[0]?.address || j.from || 'unknown';
  const snippet = [j.snippet, j.textPlain, j.bodyPlain].filter(Boolean).join('\n').slice(0, 500);
  const combined = `${subject}\n${snippet}`;

  let tag = 'INFO';
  if (/urgent|tomorrow|deadline|last call/i.test(combined)) tag = 'URGENT';
  else if (/trip|permission|consent/i.test(combined)) tag = 'ACTION';
  else if (/payment|fee|invoice/i.test(combined)) tag = 'MONEY';
  else if (/homework|assignment|exam|test/i.test(combined)) tag = 'STUDY';

  out.push({
    json: {
      chatId: 'REPLACE_CHAT_ID',
      telegramText: [
        `School email: ${tag}`,
        `From: ${from}`,
        `Subject: ${subject}`,
        '',
        snippet || '(no preview)'
      ].join('\n')
    }
  });
}
return out;
